    static int64_t active_batch = -1;
    static int64_t active_n = -1;

    const int64_t batch = input.size(0);
    if (batch != active_batch || n != active_n) {
        for (int i = 0; i < cache_size; ++i) {
            cache[i] = SmallCacheEntry{};
        }
        cache_size = 0;
        active_batch = batch;
        active_n = n;
